<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, query } from '../api/client'
import type { DatasheetOption, ManualListItem } from '../api/types'
import AppBadge from '../design-system/AppBadge.vue'
import AppDialog from '../design-system/AppDialog.vue'
import AppTable from '../design-system/AppTable.vue'
import EmptyState from '../design-system/EmptyState.vue'
import { useRouter } from 'vue-router'
import { useSessionStore } from '../stores/session'
const list = ref<ManualListItem[]>([]); const loading = ref(true); const error = ref(''); const status = ref(''); const onlyMine = ref(false)
const session = useSessionStore()
const router = useRouter()
const newOpen = ref(false); const newSaving = ref(false); const newError = ref(''); const datasheets = ref<DatasheetOption[]>([])
const newManual = ref({ MODEL_NAME: '', JOB_NUMBER: '', PROCESS_ID: '', LABEL: '', COOLING: '', OPTION_TEXT: '', DOC_VERSION: '1.0', PAGE_SIZE: 'LETTER' })
async function load() { loading.value = true; error.value = ''; try { list.value = (await api<{ list: ManualListItem[] }>(query('/api/manual/list', { status: status.value, onlyMine: onlyMine.value ? 'Y' : undefined }))).list } catch (e) { error.value = e instanceof Error ? e.message : '목록을 불러오지 못했습니다.' } finally { loading.value = false } }
async function openNew() { newError.value = ''; newManual.value = { MODEL_NAME: '', JOB_NUMBER: '', PROCESS_ID: '', LABEL: '', COOLING: '', OPTION_TEXT: '', DOC_VERSION: '1.0', PAGE_SIZE: 'LETTER' }; newOpen.value = true; try { datasheets.value = (await api<{ list: DatasheetOption[] }>('/api/manual/datasheets')).list } catch { datasheets.value = [] } }
function pickDatasheet() { newManual.value.JOB_NUMBER = datasheets.value.find(item => item.D_ID === newManual.value.PROCESS_ID)?.NAME ?? '' }
async function create() { if (!newManual.value.MODEL_NAME.trim()) { newError.value = 'Model Name 은 필수입니다.'; return }; newSaving.value = true; newError.value = ''; try { const data = await api<{ M_ID: string }>('/api/manual/create', { method: 'POST', body: JSON.stringify(newManual.value) }); newOpen.value = false; await router.push({ path: '/manual/detail', query: { mid: data.M_ID } }) } catch (e) { newError.value = e instanceof Error ? e.message : '문서를 만들지 못했습니다.' } finally { newSaving.value = false } }
function openDetail(mid: string) { router.push({ path: '/manual/detail', query: { mid } }) }
function formatDate(value: string) { return value ? new Intl.DateTimeFormat('ko-KR', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value)) : '-' }
onMounted(load)
</script>
<template><section><div class="page-title"><div><h1>Manuals</h1><p>시스템 매뉴얼을 조회하고 관리합니다.</p></div><button v-if="session.user?.CAPABILITIES.CAN_CREATE_MANUAL" class="button" @click="openNew">New Manual</button></div><div class="toolbar"><label>상태 <select v-model="status" @change="load"><option value="">전체</option><option value="DRAFT">DRAFT</option><option value="REVIEW">REVIEW</option><option value="APPROVED">APPROVED</option><option value="PUBLISHED">PUBLISHED</option><option value="OBSOLETE">OBSOLETE</option></select></label><label class="check-label"><input v-model="onlyMine" type="checkbox" @change="load" /> 내 문서만</label></div><p v-if="error" class="error">{{ error }}</p><p v-else-if="loading">불러오는 중…</p><EmptyState v-else-if="list.length === 0" title="표시할 문서가 없습니다" description="필터를 바꾸거나 새 문서를 만드세요." /><AppTable v-else><thead><tr><th>Doc No.</th><th>Model Name</th><th>Job Number</th><th>상태</th><th>Option</th><th>Requester</th><th>등록일</th></tr></thead><tbody><tr v-for="item in list" :key="item.M_ID" class="clickable-row" tabindex="0" @click="openDetail(item.M_ID)" @keydown.enter="openDetail(item.M_ID)" @keydown.space.prevent="openDetail(item.M_ID)"><td>{{ item.DOC_NUM }}</td><td>{{ item.MODEL_NAME }}<small v-if="item.MY_ROLE">{{ item.MY_ROLE }}</small></td><td>{{ item.JOB_NUMBER }}</td><td><AppBadge :status="item.STATUS" /></td><td>{{ item.OPTION_TEXT }}</td><td>{{ item.REQUESTER_NAME }}</td><td>{{ formatDate(item.REG_DT) }}</td></tr></tbody></AppTable><AppDialog v-model:open="newOpen" title="New System Manual"><p v-if="newError" class="error">{{ newError }}</p><label>Model Name<input v-model.trim="newManual.MODEL_NAME" maxlength="100" required /></label><label>Job Number<select v-model="newManual.PROCESS_ID" @change="pickDatasheet"><option value="">선택 안 함</option><option v-for="item in datasheets" :key="item.D_ID" :value="item.D_ID">{{ item.NAME }}{{ item.DS_VERSION ? ' · ' + item.DS_VERSION : '' }}</option></select><small>Datasheet 를 고르면 SPECIFICATIONS 목차에 사양이 자동으로 보입니다.</small></label><label>Label<select v-model="newManual.LABEL"><option value="">선택 안 함</option><option value="EXODUS">Exodus</option><option value="OEM">OEM</option></select></label><label>Cooling<select v-model="newManual.COOLING"><option value="">선택 안 함</option><option value="AIR">Air</option><option value="LIQUID">Liquid</option></select><small>Label·Cooling 에 맞는 필수 목차가 자동으로 들어갑니다.</small></label><label>Option<textarea v-model.trim="newManual.OPTION_TEXT" maxlength="500" /></label><label>Version<input v-model.trim="newManual.DOC_VERSION" maxlength="20" placeholder="1.0" /></label><label>Page Size<select v-model="newManual.PAGE_SIZE"><option value="LETTER">Letter (216 x 279mm)</option><option value="A4">A4 (210 x 297mm)</option></select></label><template #footer><button class="secondary" type="button" @click="newOpen = false">취소</button><button type="button" :disabled="newSaving" @click="create">{{ newSaving ? '생성 중…' : '생성' }}</button></template></AppDialog></section></template>
